/*
 * Version of the web UI build the server is running — the same stamp the
 * bundled pages carry (both come from `generated/version`, generated by
 * scripts/gen_modules.ts from package.json). Long-lived pages (the OBS
 * overlays) compare the snapshot's server version to their own bundled
 * version and reload when a new deployment replaced the server.
 *
 * Modules may only reach the core through `shared/`, so this is the door for
 * the generated stamp (distinct from `shared/version`, the device app's
 * git-based build stamp).
 */
export { APP_VERSION } from "../generated/version";
